-- ============================================================
-- EcoPath Database: Step 3 — Seed Species Data
-- 50 iconic Indian birds across all habitats and IUCN categories
-- GBIF keys verified against the GBIF Backbone Taxonomy
-- ============================================================

INSERT INTO species (gbif_key, common_name, scientific_name, family, order_name, iucn_status, endemic_india, migratory, primary_habitat, primary_range, description, fun_fact) VALUES

-- ─── ICONIC & NATIONAL SYMBOLS ───────────────────────────────────────────────
(2474543,  'Indian Peafowl',            'Pavo cristatus',           'Phasianidae',   'Galliformes',    'LC', true,  false, ARRAY['forest','agricultural'], ARRAY['Pan-India'], 'The national bird of India, famous for its spectacular iridescent tail display.', 'A peacock''s train can reach up to 1.8 metres and comprises 60% of its body length.'),
(2480537,  'Sarus Crane',               'Antigone antigone',         'Gruidae',       'Gruiformes',     'VU', false, false, ARRAY['wetland','agricultural'], ARRAY['Gangetic Plains','Gujarat'], 'The world''s tallest flying bird, found in the wetlands of northern India.', 'Sarus cranes are monogamous and mate for life; a widowed bird has been known to die of grief.'),
(2473307,  'Great Indian Bustard',      'Ardeotis nigriceps',        'Otididae',      'Otidiformes',    'CR', true,  false, ARRAY['grassland'], ARRAY['Rajasthan','Gujarat'], 'One of the heaviest flying birds, critically endangered due to habitat loss.', 'Fewer than 150 individuals remain in the wild, primarily in Rajasthan''s Desert National Park.'),
(2480851,  'Bengal Florican',           'Houbaropsis bengalensis',    'Otididae',      'Otidiformes',    'CR', false, false, ARRAY['grassland'], ARRAY['Assam','Uttar Pradesh'], 'A critically endangered bustard of Indian grasslands.', 'Males perform an extraordinary aerial dance during breeding season, leaping up to 3 metres high.'),

-- ─── RAPTORS ─────────────────────────────────────────────────────────────────
(2480866,  'Indian Vulture',            'Gyps indicus',              'Accipitridae',  'Accipitriformes','CR', true,  false, ARRAY['forest','cliff'], ARRAY['Central India','Deccan'], 'A critically endangered vulture nearly wiped out by veterinary diclofenac.', 'Vulture populations crashed by 97% in the 1990s—one of the fastest declines of any bird.'),
(2481139,  'White-rumped Vulture',      'Gyps bengalensis',          'Accipitridae',  'Accipitriformes','CR', false, false, ARRAY['forest','cliff'], ARRAY['Pan-India'], 'Once the most abundant large raptor on Earth, now critically endangered.', 'This species was so common in the 1980s that it was considered "vermin."'),
(7726978,  'Indian Fish Eagle',         'Haliaeetus leucoryphus',    'Accipitridae',  'Accipitriformes','VU', false, false, ARRAY['wetland','river'], ARRAY['Himalayan Foothills','Assam'], 'A large raptor dependent on healthy river ecosystems.', 'Its talonspan can exceed 22 cm, making it one of India''s largest eagles.'),
(2480922,  'Changeable Hawk-Eagle',     'Nisaetus cirrhatus',        'Accipitridae',  'Accipitriformes','LC', false, false, ARRAY['forest'], ARRAY['Western Ghats','Northeast India'], 'A forest raptor of the Indian subcontinent.', 'Capable of taking prey as large as peacocks and monitor lizards.'),
(2481484,  'Shaheen Falcon',            'Falco peregrinus peregrinator','Falconidae',  'Falconiformes',  'LC', false, false, ARRAY['cliff','urban'], ARRAY['Coastal India','Western Ghats'], 'The Indian subspecies of the Peregrine Falcon.', 'Can dive at over 320 km/h, making it the fastest animal on Earth.'),

-- ─── WETLAND & WATER BIRDS ───────────────────────────────────────────────────
(2480978,  'Greater Flamingo',          'Phoenicopterus roseus',     'Phoenicopteridae','Phoenicopteriformes','LC',false,true, ARRAY['wetland','coastal'], ARRAY['Gujarat','Rajasthan'], 'Massive flocks gather in the Rann of Kutch and Chilika Lake.', 'Flamingos can filter 4-6 litres of water per day through their specialized beaks.'),
(2481029,  'Lesser Flamingo',           'Phoeniconaias minor',       'Phoenicopteridae','Phoenicopteriformes','NT',false,true, ARRAY['wetland','saline'], ARRAY['Gujarat','Mumbai'], 'The world''s most numerous flamingo species, filtering blue-green algae.', 'Mumbai''s Thane Creek hosts up to 20,000 lesser flamingos during winter.'),
(2474866,  'Painted Stork',             'Mycteria leucocephala',     'Ciconiidae',    'Ciconiiformes',  'LC', false, false, ARRAY['wetland'], ARRAY['Pan-India'], 'A spectacular wading bird that nests colonially in trees near water.', 'Forages by walking through shallows with its bill open, snapping it shut on contact with prey.'),
(2481070,  'Asian Openbill',            'Anastomus oscitans',        'Ciconiidae',    'Ciconiiformes',  'LC', false, false, ARRAY['wetland','paddy fields'], ARRAY['Pan-India'], 'Named for the distinctive gap in its bill, evolved to extract apple snails.', 'Populations have boomed with rice cultivation, which creates ideal apple snail habitat.'),
(2480498,  'Black-necked Stork',        'Ephippiorhynchus asiaticus','Ciconiidae',    'Ciconiiformes',  'LC', false, false, ARRAY['wetland'], ARRAY['Gangetic Plains','Assam'], 'India''s only stork species with iridescent plumage.', 'Males and females can be distinguished by eye colour—yellow in females, brown in males.'),
(2481057,  'Spot-billed Pelican',       'Pelecanus philippensis',    'Pelecanidae',   'Pelecaniformes', 'NT', false, false, ARRAY['wetland','coastal'], ARRAY['Southern India'], 'A colonial nesting pelican found in large freshwater lakes of South India.', 'Breeds in Kokkare Bellur, Karnataka, where they nest alongside painted storks in village trees.'),
(2480432,  'Dalmatian Pelican',         'Pelecanus crispus',         'Pelecanidae',   'Pelecaniformes', 'NT', false, true,  ARRAY['wetland'], ARRAY['Gujarat','Rajasthan'], 'The world''s largest pelican, a winter visitor to Indian wetlands.', 'Its gullet pouch can hold up to 13 litres of water.'),

-- ─── FOREST BIRDS ────────────────────────────────────────────────────────────
(2476736,  'Indian Roller',             'Coracias benghalensis',     'Coraciidae',    'Coraciiformes',  'LC', false, false, ARRAY['open woodland','agricultural'], ARRAY['Pan-India'], 'The state bird of three Indian states, famous for its brilliant blue plumage.', 'Performs spectacular rolling aerial displays to attract mates, giving the family its name.'),
(2478491,  'Malabar Pied Hornbill',     'Anthracoceros coronatus',   'Bucerotidae',   'Bucerotiformes', 'NT', true,  false, ARRAY['forest'], ARRAY['Western Ghats','Sri Lanka'], 'A large hornbill dependent on old-growth forests of the Western Ghats.', 'Females seal themselves inside tree cavities with mud and dung to incubate eggs safely.'),
(2478547,  'Great Hornbill',            'Buceros bicornis',          'Bucerotidae',   'Bucerotiformes', 'VU', false, false, ARRAY['forest'], ARRAY['Western Ghats','Northeast India'], 'India''s largest hornbill, a keystone species for seed dispersal.', 'Can live for 50 years and is culturally sacred to the Nyishi people of Arunachal Pradesh.'),
(2476675,  'Malabar Trogon',            'Harpactes fasciatus',       'Trogonidae',    'Trogoniformes',  'LC', false, false, ARRAY['forest'], ARRAY['Western Ghats','Sri Lanka'], 'A gem of the Western Ghats, one of India''s most beautiful birds.', 'Nests in termite mounds, which regulate temperature and humidity for the eggs.'),
(2477062,  'White-bellied Woodpecker',  'Dryocopus javensis',        'Picidae',       'Piciformes',     'LC', false, false, ARRAY['forest'], ARRAY['Western Ghats','Northeast India'], 'India''s largest woodpecker, an indicator of old-growth forest health.', 'Its cavities are used by dozens of other species, making it a true ecosystem engineer.'),

-- ─── MIGRATORY SPECIES ───────────────────────────────────────────────────────
(2481064,  'Amur Falcon',               'Falco amurensis',           'Falconidae',    'Falconiformes',  'LC', false, true,  ARRAY['grassland','open country'], ARRAY['Nagaland','Northeast India'], 'Undertakes one of the longest migrations—from Siberia to South Africa via India.', 'Up to 100,000 Amur Falcons roost nightly in Nagaland''s Doyang Lake—the world''s largest raptor roost.'),
(2460912,  'Bar-headed Goose',          'Anser indicus',             'Anatidae',      'Anseriformes',   'LC', false, true,  ARRAY['wetland','high altitude'], ARRAY['Himalayan Lakes','Gujarat'], 'Flies over the Himalayas at altitudes exceeding 7,000 metres.', 'Recorded flying at 6,540 m over the Himalayas — the world''s highest-altitude bird migration.'),
(2481060,  'Demoiselle Crane',          'Grus virgo',                'Gruidae',       'Gruiformes',     'LC', false, true,  ARRAY['grassland','agricultural'], ARRAY['Rajasthan','Gujarat'], 'Crosses the Himalayas in vast flocks en route to wintering grounds in Rajasthan.', 'Khichan village in Rajasthan feeds 20,000+ cranes daily — a remarkable human-bird coexistence story.'),
(2474887,  'Ruddy Shelduck',            'Tadorna ferruginea',        'Anatidae',      'Anseriformes',   'LC', false, true,  ARRAY['wetland'], ARRAY['Himalayan Rivers','Rajasthan'], 'A striking orange duck that migrates from Central Asia to winter in India.', 'Considered sacred in Tibetan Buddhist culture as a symbol of happiness.'),
(2481045,  'Common Pochard',            'Aythya ferina',             'Anatidae',      'Anseriformes',   'VU', false, true,  ARRAY['wetland'], ARRAY['Pan-India'], 'A diving duck that has declined sharply across its Eurasian range.', 'Can dive up to 2.5 metres deep to feed on aquatic vegetation.'),

-- ─── ENDEMIC & THREATENED ────────────────────────────────────────────────────
(2473388,  'Nilgiri Laughingthrush',    'Montecincla cachinnans',    'Leiothrichidae','Passeriformes',  'EN', true,  false, ARRAY['shola forest'], ARRAY['Nilgiris'], 'Critically endemic to the Nilgiri shola-grassland mosaic.', 'Among only 7 bird species endemic to the Nilgiri Biosphere Reserve.'),
(9614059,  'Bugun Liocichla',           'Liocichla bugunorum',       'Leiothrichidae','Passeriformes',  'CR', true,  false, ARRAY['forest'], ARRAY['Arunachal Pradesh'], 'One of India''s rarest birds, discovered as recently as 2006.', 'Known from fewer than 14 individuals ever observed, all in Eaglenest Wildlife Sanctuary.'),
(2492397,  'Jerdon''s Courser',         'Rhinoptilus bitorquatus',   'Glareolidae',   'Charadriiformes','CR', true,  false, ARRAY['rocky ravine'], ARRAY['Andhra Pradesh'], 'A critically endangered nocturnal bird rediscovered in 1986 after 86 years.', 'So secretive that it was classified as extinct until 1986 when it was rediscovered.'),
(5228002,  'Forest Owlet',              'Athene blewitti',           'Strigidae',     'Strigiformes',   'EN', true,  false, ARRAY['dry deciduous forest'], ARRAY['Central India'], 'Rediscovered in 1997 after 113 years of presumed extinction.', 'One of the rarest owls in the world, with a total population estimated at 250-600 individuals.'),
(2480522,  'Indian Spotted Eagle',      'Clanga hastata',            'Accipitridae',  'Accipitriformes','VU', false, true,  ARRAY['grassland','wetland'], ARRAY['Gangetic Plains','Northwest India'], 'A vulnerable eagle that winters on the Indian plains.', 'Hybridizes with the Greater Spotted Eagle, making population counts challenging.'),

-- ─── WETLAND SPECIALISTS ─────────────────────────────────────────────────────
(2481047,  'Purple Swamphen',           'Porphyrio porphyrio',       'Rallidae',      'Gruiformes',     'LC', false, false, ARRAY['wetland','marsh'], ARRAY['Pan-India'], 'A large, brilliantly purple rail common in Indian marshes.', 'Uses its feet like hands—holds food with one foot while eating with the other.'),
(2481035,  'Pheasant-tailed Jacana',   'Hydrophasianus chirurgus',  'Jacanidae',     'Charadriiformes','LC', false, false, ARRAY['wetland'], ARRAY['Pan-India'], 'Walks on floating lotus leaves with its enormous feet.', 'One of the few bird species where the male incubates eggs and raises chicks alone.'),
(2480892,  'Bronze-winged Jacana',      'Metopidius indicus',        'Jacanidae',     'Charadriiformes','LC', false, false, ARRAY['wetland'], ARRAY['Pan-India'], 'A specialist of densely vegetated freshwater marshes.', 'Has the longest toes relative to body size of any Indian bird.'),
(5846877,  'Indian River Tern',         'Sterna aurantia',           'Laridae',       'Charadriiformes','NT', false, false, ARRAY['river'], ARRAY['Major Indian Rivers'], 'A specialist of large, undisturbed river sandbars.', 'Nests on exposed sandbars—its population is a direct indicator of river ecosystem health.'),
(2481091,  'Black-bellied Tern',        'Sterna acuticauda',         'Laridae',       'Charadriiformes','EN', false, false, ARRAY['river'], ARRAY['Gangetic Plains'], 'An endangered river tern declining due to sand mining and dam construction.', 'Requires clean sandy river islands for nesting—riverbed sand mining is its primary threat.'),

-- ─── FOREST PASSERINES ───────────────────────────────────────────────────────
(2492124,  'Indian Paradise Flycatcher','Terpsiphone paradisi',      'Monarchidae',   'Passeriformes',  'LC', false, false, ARRAY['forest','garden'], ARRAY['Pan-India'], 'One of India''s most beautiful birds, with males carrying a 30 cm ribbon-like tail.', 'The male has two colour morphs—white and chestnut—and the tail ribbon takes 2 years to grow.'),
(2492175,  'Asian Fairy-bluebird',      'Irena puella',              'Irenidae',      'Passeriformes',  'LC', false, false, ARRAY['rainforest'], ARRAY['Western Ghats','Northeast India'], 'A stunning electric-blue bird of the forest canopy.', 'An important seed disperser for rainforest plants, particularly wild nutmegs.'),
(2487920,  'Malabar Whistling Thrush',  'Myophonus horsfieldii',     'Muscicapidae',  'Passeriformes',  'LC', true,  false, ARRAY['forest stream'], ARRAY['Western Ghats'], 'Known locally as the "Whistling Schoolboy" for its melodic, human-like whistling.', 'Sings only at dawn and dusk along rocky stream banks in the Western Ghats.'),
(2481126,  'Indian Pitta',              'Pitta brachyura',           'Pittidae',      'Passeriformes',  'LC', false, true,  ARRAY['forest'], ARRAY['Central India','Western Ghats'], 'A jewel-like bird with nine colours, a summer breeder in Indian forests.', 'Navigates using Earth''s magnetic field during its remarkable nocturnal migrations.'),
(2484985,  'White-rumped Shama',        'Kittacincla malabarica',    'Muscicapidae',  'Passeriformes',  'LC', false, false, ARRAY['forest'], ARRAY['Western Ghats','Northeast India'], 'One of Asia''s finest songbirds, producing incredibly complex melodic phrases.', 'Can mimic the songs of many other bird species, incorporating them into its own repertoire.'),

-- ─── GRASSLAND & OPEN COUNTRY ────────────────────────────────────────────────
(2473402,  'Bristled Grassbird',        'Schoenicola striatus',      'Locustellidae', 'Passeriformes',  'VU', false, false, ARRAY['tall grassland'], ARRAY['Assam','Maharashtra'], 'A vulnerable grassland specialist dependent on unburnt tall grass.', 'Rarely seen but identified by its distinctive grasshopper-like buzzing song.'),
(5848333,  'Finn''s Weaver',            'Ploceus megarhynchus',      'Ploceidae',     'Passeriformes',  'VU', true,  false, ARRAY['tall grassland'], ARRAY['Uttar Pradesh','Uttarakhand'], 'A vulnerable colonial weaver of tall elephant grass along foothills.', 'Weaves elaborate hanging nests—a single colony can contain 300 nests in one tree.'),
(2473308,  'Sociable Lapwing',          'Vanellus gregarius',        'Charadriidae',  'Charadriiformes','CR', false, true,  ARRAY['grassland','dry land'], ARRAY['Northwest India'], 'A critically endangered winter visitor to Indian plains.', 'One of the world''s 100 most threatened birds; its entire population may be under 10,000.'),

-- ─── COASTAL & MARINE ────────────────────────────────────────────────────────
(2480534,  'Crab Plover',               'Dromas ardeola',            'Dromadidae',    'Charadriiformes','LC', false, true,  ARRAY['coastal'], ARRAY['Gulf of Kutch','Lakshadweep'], 'The only member of its family, nesting colonially in sand burrows.', 'The only shore bird that feeds its chicks after fledgling—a unique trait among waders.'),
(2480671,  'Indian Skimmer',            'Rynchops albicollis',       'Laridae',       'Charadriiformes','EN', false, false, ARRAY['river','coastal'], ARRAY['Central India Rivers'], 'Hunts by skimming the water surface with its elongated lower mandible.', 'The lower mandible grows faster than the upper—an adaptation unique to skimmers worldwide.'),
(2481080,  'Lesser Noddy',              'Anous tenuirostris',        'Laridae',       'Charadriiformes','LC', false, false, ARRAY['coastal','marine'], ARRAY['Lakshadweep'], 'A seabird that breeds in enormous colonies on the atolls of Lakshadweep.', 'Catches fish by hovering above schools driven to the surface by tuna and dolphins.'),

-- ─── HIGH ALTITUDE & HIMALAYAN ───────────────────────────────────────────────
(2474660,  'Himalayan Monal',           'Lophophorus impejanus',     'Phasianidae',   'Galliformes',    'LC', false, false, ARRAY['alpine forest','high altitude'], ARRAY['Himalayas'], 'The national bird of Nepal and state bird of Uttarakhand.', 'Males have nine colours of iridescent plumage—more colour variation than almost any other bird.'),
(2480538,  'Blood Pheasant',            'Ithaginis cruentus',        'Phasianidae',   'Galliformes',    'LC', false, false, ARRAY['high altitude forest'], ARRAY['Eastern Himalayas'], 'A high-altitude pheasant living between 3,000-5,000m elevation.', 'One of the few pheasants that regularly eats snow to supplement water intake.'),
(2480954,  'Snow Partridge',            'Lerwa lerwa',               'Phasianidae',   'Galliformes',    'LC', false, false, ARRAY['alpine','snow zone'], ARRAY['Himalayas'], 'A hardy partridge of the high Himalayan snowfields.', 'Has red legs, bill, and eye-ring making it stand out brilliantly against white snow.');

-- Update ingestion timestamp
UPDATE species SET ingested_at = NOW() WHERE ingested_at IS NULL;

-- Verify seed data
SELECT COUNT(*) as total_species,
       COUNT(CASE WHEN iucn_status IN ('CR','EN') THEN 1 END) as threatened,
       COUNT(CASE WHEN migratory = true THEN 1 END) as migratory,
       COUNT(CASE WHEN endemic_india = true THEN 1 END) as endemic
FROM species;
